CREATE OR REPLACE FUNCTION public.fn_cash_session_open(p_user_id uuid, p_table_id uuid, p_buy_in numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t record; v_id uuid; v_stay integer := 600000; v_rejoin integer := 7200000; v_snap jsonb;
BEGIN
  SELECT t.id, t.club_id, t.game_variant, t.small_blind, t.big_blind, t.tournament_id, t.cluster_id
    INTO v_t FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND OR v_t.tournament_id IS NOT NULL THEN RETURN NULL; END IF;

  -- A game's snapshot may RAISE the two clocks (never lower: CHECK floors on
  -- the session row and the create function both refuse it).
  IF v_t.cluster_id IS NOT NULL THEN
    SELECT g.ruleset_snapshot INTO v_snap FROM public.cash_games g WHERE g.id = v_t.cluster_id;
    IF v_snap IS NOT NULL THEN
      v_stay   := GREATEST(600000,  coalesce((v_snap->>'stay_clock_min')::integer, 10) * 60000);
      v_rejoin := GREATEST(7200000, coalesce((v_snap->>'rejoin_window_min')::integer, 120) * 60000);
    END IF;
  END IF;

  IF p_buy_in IS NOT NULL THEN
    UPDATE public.cash_player_session
       SET closed_at = clock_timestamp(), closed_reason = 'stale_on_reopen'
     WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id
       AND closed_at IS NULL;
  END IF;

  INSERT INTO public.cash_player_session
    (player_id, club_id, scope_type, scope_id, table_id, variant, sb, bb, baseline,
     stay_clock_ms, rejoin_window_ms, stay_remaining_ms, stay_running, stay_last_tick_at, opened_at)
  VALUES
    (p_user_id, v_t.club_id, 'table', p_table_id, p_table_id, v_t.game_variant,
     v_t.small_blind, v_t.big_blind, GREATEST(COALESCE(p_buy_in, 0), 0),
     v_stay, v_rejoin, v_stay, false, clock_timestamp(), clock_timestamp())
  ON CONFLICT (player_id, scope_type, scope_id) WHERE closed_at IS NULL DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.cash_player_session
     WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id
       AND closed_at IS NULL;
  END IF;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_nit_check(p_table_id uuid, p_user_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_on            boolean;
  v_career_min    integer;
  v_maintain_min  integer;
  v_maintain_n    integer;
  v_game          uuid;
  v_since         timestamptz;
  v_career_floor  integer;
  v_career_hands  integer;
  v_career_vpip   numeric;
  v_table_hands   integer;
  v_table_vpip    numeric;
BEGIN
  SELECT COALESCE(t.nit_game, false),
         GREATEST(COALESCE(t.career_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_hands, 10), 1),
         t.cluster_id
    INTO v_on, v_career_min, v_maintain_min, v_maintain_n, v_game
    FROM public.tables t WHERE t.id = p_table_id LIMIT 1;

  -- The toggle is the master switch. With NIT Game off the three numbers do
  -- nothing, which is what a switch labelled "Penalty for tight play" means
  -- and what makes the numbers safe to leave at their defaults.
  IF NOT COALESCE(v_on, false) THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nit_game_off');
  END IF;

  -- CAREER
  IF v_career_min > 0 THEN
    v_career_floor := GREATEST(v_maintain_n * 10, 100);
    SELECT count(*)::int,
           CASE WHEN count(*) = 0 THEN NULL
                ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
      INTO v_career_hands, v_career_vpip
      FROM public.ca_hand_facts f
     WHERE f.user_id = p_user_id;

    IF v_career_hands >= v_career_floor AND v_career_vpip < v_career_min THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'career_vpip',
        'vpip', v_career_vpip, 'required', v_career_min, 'hands', v_career_hands);
    END IF;
  END IF;

  -- MAINTAIN
  -- THE SITTING IN THE GAME, NOT THE CHAIR (2026-09-09, lane E audit). Dan:
  -- "IF ANYONE FALLS UNDER THE SET THRESHOLD FOR THE GAME AFTER 10 HANDS".
  -- A must-move game opens a fresh chair on every move, and judging "this
  -- table since this chair" restarted the window at zero each time - on
  -- Madness the median sitting at one table was six hands against a ten-hand
  -- window, so the floor could never judge a player the game kept moving.
  -- On a cluster table the sample is every fact row on any table of the game
  -- since the roster row's joined_at (a move does not close it; a leave
  -- does, so a player who rebuys after a break still starts a fresh count).
  -- A table outside a cluster keeps the per-table rule.
  IF v_maintain_min > 0 THEN
    v_since := p_since;
    IF v_game IS NOT NULL THEN
      SELECT r.joined_at INTO v_since
        FROM public.cash_game_roster r
       WHERE r.game_id = v_game AND r.user_id = p_user_id AND r.left_at IS NULL
       ORDER BY r.joined_at DESC
       LIMIT 1;
      IF NOT FOUND THEN v_since := p_since; END IF;

      SELECT count(*)::int,
             CASE WHEN count(*) = 0 THEN NULL
                  ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
        INTO v_table_hands, v_table_vpip
        FROM public.ca_hand_facts f
       WHERE f.user_id = p_user_id
         AND (v_since IS NULL OR f.played_at >= v_since)
         AND f.table_id IN (SELECT t2.id FROM public.tables t2 WHERE t2.cluster_id = v_game);
    ELSE
      SELECT count(*)::int,
             CASE WHEN count(*) = 0 THEN NULL
                  ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
        INTO v_table_hands, v_table_vpip
        FROM public.ca_hand_facts f
       WHERE f.table_id = p_table_id
         AND f.user_id = p_user_id
         AND (v_since IS NULL OR f.played_at >= v_since);
    END IF;

    IF v_table_hands >= v_maintain_n AND v_table_vpip < v_maintain_min THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'maintain_vpip',
        'vpip', v_table_vpip, 'required', v_maintain_min, 'hands', v_table_hands);
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'reason', 'within_limits');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_seat_club_for_user(p_user_id uuid, p_table_id uuid, p_preferred_club uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_union uuid; v_table_club uuid;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_table_club
    FROM public.tables t WHERE t.id = p_table_id;
  IF v_union IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.club_members cm
       WHERE cm.user_id = p_user_id AND cm.club_id = v_table_club
         AND cm.status IN ('active','approved')
    ) THEN RETURN v_table_club; END IF;
    RETURN public.fn_player_home_club(p_user_id, p_preferred_club);
  END IF;
  RETURN public.fn_seat_club_for_user_membership_unchecked(
    p_user_id, p_table_id, p_preferred_club
  );
END;
$function$
